func TestErrInvalidType(t *testing.T) {
	_, err := BuildReport(Artifact{Name: ""}, nil, nil)
	var ei errInvalid
	if !errors.As(err, &ei) {
		t.Fatalf("expected errInvalid, got %T %v", err, err)
	}
